def main():
    t = int(input())
    for _ in range(t):
        s = input().strip()
        n = len(s)
        c10 = 0
        mixed = 0
        i = 0
        while i < n:
            j = i
            while j + 1 < n and not (s[j] == '1' and s[j+1] == '0'):
                j += 1
            block = s[i:j+1]
            if '0' in block and '1' in block:
                mixed += 1
            i = j + 1
        for k in range(n - 1):
            if s[k] == '1' and s[k+1] == '0':
                c10 += 1
        if mixed == 0:
            print(c10 + 1)
        else:
            print(c10 + mixed)

if __name__ == '__main__':
    main()
